import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getPurchaseHistoryHandler } from "../handlers/getPurchaseHistoryHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof getPurchaseHistoryHandler>>;

export function useGetPurchaseHistory(
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getPurchaseHistory", bookmark],
    queryFn: () => getPurchaseHistoryHandler(bookmark),
    ...options,
  });
}
